+:root {
+  font-family: "Trebuchet MS", "Segoe UI", sans-serif;
+  color: #263238;
+  background: #f4f6f8;
+  --page-gutter: clamp(1rem, 5vw, 5rem);
+  --content-width: 72rem;
+}
+* { box-sizing: border-box; }
+body { margin: 0; line-height: 1.6; }
+h1, h2, h3, p { margin: 0; }
+h1, h2, h3, .brand {
+  font-family: Georgia, "Times New Roman", serif;
+  line-height: 1.2;
+  overflow-wrap: break-word;
+}
+h2 { font-size: clamp(1.75rem, 3vw, 2.25rem); }
+h3 { font-size: 1.4rem; }
+p { overflow-wrap: break-word; }
+.container {
+  width: min(var(--content-width), calc(100% - 2 * var(--page-gutter)));
+  margin-inline: auto;
+}
+header { background: #17324d; color: #fff; }
+.header-inner {
+  min-height: 4.5rem;
+  padding-block: 1rem;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  flex-wrap: wrap;
+  gap: .75rem 2rem;
+}
+.brand { font-size: 1.5rem; }
+nav { display: flex; flex-wrap: wrap; gap: .25rem 1.5rem; }
+nav a {
+  display: inline-flex;
+  align-items: center;
+  min-height: 2.75rem;
+  color: #fff;
+  text-decoration: none;
+}
+nav a:hover { text-decoration: underline; text-underline-offset: .3em; }
+.notice { background: #ffe3a3; }
+.notice .container { padding-block: .75rem; }
+.hero {
+  padding-block: clamp(3rem, 8vw, 6rem);
+  min-height: 25rem;
+  display: flex;
+  align-items: center;
+  background: linear-gradient(90deg, #10283de6, #10283d80), url("business.jpg") center / cover;
+  color: #fff;
+}
+.hero h1 { font-size: clamp(2.5rem, 7vw, 4rem); }
+.hero p { max-width: 38rem; margin-top: 1.25rem; font-size: 1.125rem; }
+.btn, button {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  min-height: 2.75rem;
+  max-width: 100%;
+  margin-top: 1.5rem;
+  padding: .75rem 1.5rem;
+  background: #e99112;
+  color: #10283d;
+  border: 0;
+  border-radius: .35rem;
+  font: inherit;
+  font-weight: 700;
+  text-align: center;
+  text-decoration: none;
+  cursor: pointer;
+}
